package com.smarthub.plus;
import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;

/** Unified online-free index of the device's real apps, imported channels and app settings. */
public final class HubSearchActivity extends HubActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private EditText query;private TextView status;private ListView list;private boolean closed,ready;private int generation;private List<AppCatalogue.App> apps=Collections.emptyList();private final List<Hit> hits=new ArrayList<>();
 private static final class Hit{final String label,kind;final Runnable open;Hit(String l,String k,Runnable o){label=l;kind=k;open=o;}}
 private final Runnable filter=()->search();
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=col();root.setBackgroundColor(BG);root.setPadding(dp(28),dp(20),dp(28),dp(20));root.setLayoutDirection(ar?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);LinearLayout head=row();head.addView(text(tx("البحث في IRAQhub","Search IRAQhub"),28,true),new LinearLayout.LayoutParams(0,-2,1));Button back=button(tx("رجوع","Back"));back.setOnClickListener(v->finish());head.addView(back);root.addView(head);query=field(root,tx("قناة، تطبيق أو إعداد","Channel, application or setting"),"");status=text(tx("قراءة الفهارس…","Reading indexes…"),13,false);status.setTextColor(MUTED);root.addView(status);list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);list.setOnItemClickListener((p,v,index,id)->hits.get(index).open.run());query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){main.removeCallbacks(filter);main.postDelayed(filter,160);}public void afterTextChanged(Editable e){}});io.execute(()->{apps=AppCatalogue.load(this);ReceiverCatalog.get(this).ensure();main.post(()->{if(!closed){ready=true;search();}});});}
 private void search(){if(!ready)return;String entered=query.getText().toString(),q=ReceiverChannelRepository.searchKey(entered);int token=++generation;io.execute(()->{List<Hit> found=new ArrayList<>();String[] labels={tx("إعدادات IRAQhub","IRAQhub settings"),tx("شريط المعلومات","Information bar"),tx("الترجمة","Subtitles"),tx("الشعارات","Channel logos"),tx("البث والبحث","Broadcast and scanning")};Class<?>[] pages={HubSettingsActivity.class,OsdSettingsActivity.class,SatelliteActivity.class,LogoSourcesActivity.class,ReceiverToolsActivity.class};for(int n=0;n<labels.length;n++)if(q.isEmpty()||ReceiverChannelRepository.searchKey(labels[n]).contains(q)){Class<?> destination=pages[n];found.add(new Hit(labels[n],tx("إعداد","Setting"),()->startActivity(new Intent(this,destination))));}for(AppCatalogue.App app:apps)if(q.isEmpty()||ReceiverChannelRepository.searchKey(app.label+" "+app.pkg).contains(q)){found.add(new Hit(app.label,tx("تطبيق","App"),()->{try{startActivity(AppCatalogue.launch(app));}catch(Exception unavailable){toast(tx("تعذر فتح التطبيق","Could not open app"));}}));if(found.size()>24&&q.isEmpty())break;}List<ReceiverCatalog.Channel> channels=ReceiverCatalog.get(this).channels(entered,-1,-1,false,true);for(int n=0;n<Math.min(30,channels.size());n++){ReceiverCatalog.Channel ch=channels.get(n);found.add(new Hit(ch.name+" · "+ch.satName,"CHL",()->startActivity(new Intent(this,ReceiverChannelsActivity.class).putExtra("query",ch.name))));}main.post(()->{if(closed||token!=generation)return;hits.clear();hits.addAll(found);status.setText(tx("النتائج: ","Results: ")+hits.size());list.setAdapter(new BaseAdapter(){public int getCount(){return hits.size();}public Object getItem(int p){return hits.get(p);}public long getItemId(int p){return p;}public View getView(int p,View recycled,ViewGroup parent){TextView row=text(hits.get(p).label+"\n"+hits.get(p).kind,18,true);row.setPadding(dp(16),dp(12),dp(16),dp(12));row.setBackground(selection(PANEL));return row;}});});});}
 @Override protected void onDestroy(){closed=true;generation++;main.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
